/* Native installation service library. Every byte of package/transaction logic
   runs in ring 3. Kernel only supplies ordinary file, lease and sync primitives. */
#include "package.h"
#define BASE "/home/user/.sino"
#define JOURNAL BASE "/rollback/journal"
#define TX_MAX 32
typedef struct {char path[128];i32 old_size;u32 dir;} Undo;
typedef struct {u32 magic,state,count,crc;Undo undo[TX_MAX];} Journal;
static Journal journal;
static u8 scratch[MAX_FILE];
static AppRecord old_record;
static int active;
void (*install_progress)(u32,u32);
u32 checksum(const void *data,u32 bytes){const u8 *p=data;u32 c=0xffffffffu;while(bytes--){c^=*p++;for(int i=0;i<8;i++)c=(c>>1)^((c&1)?0xedb88320u:0);}return c^0xffffffffu;}
int safe_id(const char *s){u32 n=0;if(!s[0])return 0;for(;s[n];n++){if(n>=24)return 0;char c=s[n];if(!((c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_'))return 0;}return 1;}
static int starts(const char *s,const char *p){while(*p)if(*s++!=*p++)return 0;return 1;}
static int relative(const char *p){if(!*p||*p=='/'||*p=='\\')return 0;u32 component=0;char part[32];for(u32 i=0;;i++){char c=p[i];if(c=='\\'||c==':'||((u8)c<32&&c))return 0;if(c=='/'||!c){if(!component)return 0;part[component]=0;if(streq(part,".")||streq(part,".."))return 0;component=0;if(!c)break;}else{if(component>=31)return 0;part[component++]=c;}}return 1;}
static int terminated(const char *s,u32 size){for(u32 i=0;i<size;i++)if(!s[i])return 1;return 0;}
static int root_valid(const char *p){if(!starts(p,"/home/user/Programs/")||strlen(p)>88)return 0;return safe_id(p+20);}
static int version_valid(const char *s){for(int part=0;part<3;part++){int digits=0;while(*s>='0'&&*s<='9'){s++;if(++digits>4)return 0;}if(!digits)return 0;if(part<2){if(*s++!='.')return 0;}else if(*s)return 0;}return 1;}
 static int record_valid(const AppRecord *r){const Package *p=&r->manifest;if(r->magic!=APP_RECORD_MAGIC||!terminated(r->root,128)||!root_valid(r->root)||!terminated(r->source,128)||p->files>PACKAGE_FILES||!p->files||!terminated(p->id,32)||!safe_id(p->id)||!terminated(p->version,16)||!version_valid(p->version)||!terminated(p->entry,64)||!relative(p->entry)||!terminated(p->config_key,32)||!terminated(p->shortcut,32)||!terminated(p->association,16))return 0;if((p->config_key[0]&&!safe_id(p->config_key))||(p->shortcut[0]&&!safe_id(p->shortcut))||(p->association[0]&&!safe_id(p->association)))return 0;for(u32 i=0;i<p->files;i++)if(!terminated(p->file[i].path,64)||!relative(p->file[i].path))return 0;return 1;}
 int PackageValidate(const Package *p,u32 bytes){if(bytes<sizeof(*p)||bytes>MAX_FILE||p->magic!=PACKAGE_MAGIC||p->format!=1||p->arch!=386||p->abi!=1||p->total_bytes!=bytes||!p->files||p->files>PACKAGE_FILES||!p->components||p->components>3||p->permissions)return S_INVALID;
 if(!terminated(p->id,32)||!safe_id(p->id)||!terminated(p->name,64)||!terminated(p->version,16)||!version_valid(p->version)||!terminated(p->entry,64)||!relative(p->entry)||!terminated(p->license,256)||!terminated(p->config_key,32)||!terminated(p->config_value,128)||!terminated(p->shortcut,32)||!terminated(p->association,16)||!terminated(p->service,32))return S_INVALID;
 if(p->config_key[0]&&!safe_id(p->config_key))return S_INVALID;if(p->shortcut[0]&&!safe_id(p->shortcut))return S_INVALID;if(p->association[0]&&!safe_id(p->association))return S_INVALID;if(p->service[0])return S_DENIED;/* Service execution not supported in ABI 1. */
 for(u32 i=0;i<sizeof(p->signature);i++)if(p->signature[i])return S_DENIED;int entry=0;
 for(u32 i=0;i<p->files;i++){const PackageFile *f=&p->file[i];if(!terminated(f->path,64)||!relative(f->path)||!f->component||(f->component&~p->components)||f->offset<sizeof(*p)||f->size>bytes||f->offset>bytes-f->size||checksum((const u8 *)p+f->offset,f->size)!=f->crc)return S_INVALID;for(u32 j=0;j<i;j++)if(streq(p->file[j].path,f->path))return S_INVALID;if(streq(f->path,p->entry)){if(!(f->component&1)||f->size<sizeof(NativeHeader))return S_INVALID;const NativeHeader *h=(const NativeHeader *)((const u8 *)p+f->offset);if(h->magic!=NATIVE_MAGIC||h->abi!=1||h->image_bytes!=f->size||h->entry<32||h->entry>=h->data_offset||h->data_offset>h->image_bytes||(h->data_offset&4095)||h->memory_bytes<h->image_bytes||h->memory_bytes>USER_BYTES||h->reserved[0]||h->reserved[1])return S_INVALID;entry=1;}}
 return entry?0:S_INVALID;}
static void join(char *out,const char *a,const char *b){copy(out,a);u32 n=strlen(out);out[n++]='/';copy(out+n,b);}
static void record_path(char *out,const char *id){join(out,BASE "/apps",id);copy(out+strlen(out),".rec");}
static void backup_path(char *out,u32 index){copy(out,BASE "/rollback/b");number(index,out+strlen(out));}
static int persist(void){journal.crc=0;journal.crc=checksum(&journal,sizeof(journal));return Write(JOURNAL,&journal,sizeof(journal))<0||Sync()<0?S_IO:0;}
static int infra(void){if(api(SYS_LEASE,(u32)"sino.install",0,0)<0)return S_BUSY;const char *dirs[]={BASE,BASE "/rollback",BASE "/apps",BASE "/config",BASE "/cache",BASE "/menu",BASE "/assoc","/home/user/Programs"};for(u32 i=0;i<8;i++)if(Mkdir(dirs[i])<0)return S_IO;return 0;}
static int cleanup(void){char path[128];for(u32 i=0;i<journal.count;i++){backup_path(path,i);Remove(path,0);}if(Remove(JOURNAL,0)<0)return S_IO;active=0;return Sync();}
int InstallRecover(void){int r=infra();if(r<0)return r;int n=Read(JOURNAL,&journal,sizeof(journal));if(n==S_NOTFOUND)return 0;if(n!=(int)sizeof(journal)||journal.magic!=0x314e5854u||journal.count>TX_MAX||(journal.state!=1&&journal.state!=2))return S_IO;u32 saved=journal.crc;journal.crc=0;if(checksum(&journal,sizeof(journal))!=saved)return S_IO;journal.crc=saved;for(u32 i=0;i<journal.count;i++)if(!terminated(journal.undo[i].path,128)||!starts(journal.undo[i].path,"/home/user/")||journal.undo[i].old_size< -1||journal.undo[i].old_size>(int)MAX_FILE||journal.undo[i].dir>1)return S_IO;active=1;if(journal.state==2)return cleanup();InstallLog("Recovering interrupted installation");return InstallRollback();}
int InstallBegin(void){if(active)return S_BUSY;int r=InstallRecover();if(r<0)return r;memset(&journal,0,sizeof(journal));journal.magic=0x314e5854u;journal.state=1;active=1;if(persist()<0){active=0;return S_IO;}return 0;}
static int snapshot(const char *path,int dir){if(!active||journal.count>=TX_MAX||strlen(path)>=128||!starts(path,"/home/user/"))return S_INVALID;for(u32 i=0;i<journal.count;i++)if(streq(journal.undo[i].path,path))return 0;Undo *u=&journal.undo[journal.count];memset(u,0,sizeof(*u));copy(u->path,path);u->dir=(u32)dir;u->old_size=-1;
 if(!dir){int n=Read(path,scratch,sizeof(scratch));if(n>=0){char backup[128];backup_path(backup,journal.count);if(Write(backup,scratch,(u32)n)<0||Sync()<0)return S_IO;u->old_size=n;}else if(n!=S_NOTFOUND)return n;}
 journal.count++;return persist();}
static int ensure_dir(const char *path){FileInfo info[1];int n=List(path,info,1);if(n>=0)return 0;if(n!=S_NOTFOUND)return n;int r=snapshot(path,1);if(r<0)return r;return Mkdir(path);}
static int parents(const char *path){char part[128];copy(part,path);for(u32 i=11;part[i];i++)if(part[i]=='/'){part[i]=0;int r=ensure_dir(part);part[i]='/';if(r<0)return r;}return 0;}
int InstallWriteFile(const char *path,const void *data,u32 bytes){if(!active||bytes>MAX_FILE)return S_INVALID;int r=parents(path);if(r<0)return r;r=snapshot(path,0);return r<0?r:Write(path,data,bytes);}
static int remove_file(const char *path){int r=snapshot(path,0);if(r<0)return r;r=Read(path,scratch,sizeof(scratch));return r==S_NOTFOUND?0:r<0?r:Remove(path,0);}
int InstallSetConfig(const char *key,const char *value){if(!safe_id(key)||strlen(value)>127)return S_INVALID;char path[128];join(path,BASE "/config",key);return InstallWriteFile(path,value,strlen(value));}
int ConfigRead(const char *key,char *out,u32 cap){if(!safe_id(key)||!cap)return S_INVALID;char path[128];join(path,BASE "/config",key);int n=Read(path,out,cap-1);if(n>=0)out[n]=0;return n;}
static int shortcut(const char *name,const char *target,const char *label){if(!safe_id(name)||strlen(target)>=128)return S_INVALID;char path[128];join(path,"/home/user/Desktop",name);copy(path+strlen(path),".lnk");char contents[200];copy(contents,target);if(label){copy(contents+strlen(contents),"\n");copy(contents+strlen(contents),label);}int r=InstallWriteFile(path,contents,strlen(contents));if(r<0)return r;join(path,BASE "/menu",name);copy(path+strlen(path),".lnk");return InstallWriteFile(path,contents,strlen(contents));}
int InstallCreateShortcut(const char *name,const char *target){return shortcut(name,target,0);}
int InstallRegisterUninstall(const AppRecord *record){char path[128];record_path(path,record->manifest.id);return InstallWriteFile(path,record,sizeof(*record));}
int InstallRollback(void){if(!active)return 0;char backup[128];for(u32 i=journal.count;i>0;i--){Undo *u=&journal.undo[i-1];if(u->dir){/* Remove only empty directories created by this transaction. */if(Remove(u->path,1)<0){FileInfo info[1];if(List(u->path,info,1)!=S_NOTFOUND)return S_IO;}}else if(u->old_size<0){int n=Read(u->path,scratch,sizeof(scratch));if(n>=0&&Remove(u->path,0)<0)return S_IO;else if(n<0&&n!=S_NOTFOUND)return S_IO;}else{backup_path(backup,i-1);int n=Read(backup,scratch,sizeof(scratch));if(n!=u->old_size||Write(u->path,scratch,(u32)n)<0)return S_IO;}}if(Sync()<0)return S_IO;journal.state=2;if(persist()<0)return S_IO;InstallLog("Transaction rolled back");return cleanup();}
int InstallCommit(void){if(!active)return S_INVALID;if(Sync()<0)return S_IO;journal.state=2;if(persist()<0)return S_IO;InstallLog("Transaction committed");return cleanup();}
void InstallLog(const char *text){char log[2048];int n=Read(BASE "/install.log",log,sizeof(log)-160);if(n<0)n=0;u32 size=strlen(text);if(size>150)size=150;memcpy(log+n,text,size);log[n+size]='\n';Write(BASE "/install.log",log,(u32)n+size+1);Log("INSTALL: ");Log(text);Log("\n");}
static int version_cmp(const char *a,const char *b){for(int i=0;i<3;i++){u32 x=0,y=0;while(*a>='0'&&*a<='9'){if(x>9999)return -1;x=x*10+(u32)(*a++-'0');}while(*b>='0'&&*b<='9'){if(y>9999)return 1;y=y*10+(u32)(*b++-'0');}if(x!=y)return x>y?1:-1;if(*a=='.')a++;if(*b=='.')b++;}return 0;}
int InstallPackage(const Package *p,const char *source,const char *root,u32 components,int fail_after){int recovery=InstallRecover();if(recovery<0)return recovery;int r=PackageValidate(p,p->total_bytes);if(r<0||!root_valid(root)||strlen(source)>=128)return S_INVALID;components=(components&p->components)|1;char path[128],entry[128];record_path(path,p->id);int n=Read(path,&old_record,sizeof(old_record));if(n>=0){if(n!=(int)sizeof(old_record)||!record_valid(&old_record)||!streq(old_record.root,root)||version_cmp(p->version,old_record.manifest.version)<0)return S_INVALID;/* Refuse ownership/config changes until shared-component policy exists. */if(!streq(p->config_key,old_record.manifest.config_key)||!streq(p->shortcut,old_record.manifest.shortcut)||!streq(p->association,old_record.manifest.association))return S_INVALID;}else if(n!=S_NOTFOUND)return n;
 /* Reject takeover of existing files and names owned by another installation. */
 for(u32 i=0;i<p->files;i++){int owned=0;if(n>=0)for(u32 j=0;j<old_record.manifest.files;j++)if(streq(p->file[i].path,old_record.manifest.file[j].path))owned=1;if(!owned){join(path,root,p->file[i].path);if(Read(path,scratch,sizeof(scratch))!=S_NOTFOUND)return S_EXISTS;}}
 if(n<0){if(p->config_key[0]){join(path,BASE "/config",p->config_key);if(Read(path,scratch,sizeof(scratch))!=S_NOTFOUND)return S_EXISTS;}if(p->shortcut[0]){join(path,"/home/user/Desktop",p->shortcut);copy(path+strlen(path),".lnk");if(Read(path,scratch,sizeof(scratch))!=S_NOTFOUND)return S_EXISTS;join(path,BASE "/menu",p->shortcut);copy(path+strlen(path),".lnk");if(Read(path,scratch,sizeof(scratch))!=S_NOTFOUND)return S_EXISTS;}if(p->association[0]){join(path,BASE "/assoc",p->association);if(Read(path,scratch,sizeof(scratch))!=S_NOTFOUND)return S_EXISTS;}}
 r=InstallBegin();if(r<0)return r;InstallLog(n>=0?"Upgrade/repair started":"Install started");if(n>=0)for(u32 i=0;i<old_record.manifest.files;i++){int keep=0;for(u32 j=0;j<p->files;j++)if(streq(old_record.manifest.file[i].path,p->file[j].path)&&(p->file[j].component&components))keep=1;if(!keep){join(path,root,old_record.manifest.file[i].path);r=remove_file(path);if(r<0)goto failed;}}
 for(u32 i=0;i<p->files;i++)if(p->file[i].component&components){join(path,root,p->file[i].path);r=InstallWriteFile(path,(const u8 *)p+p->file[i].offset,p->file[i].size);if(r<0)goto failed;if(install_progress)install_progress(i+1,p->files);if(fail_after==(int)i+1){r=S_IO;goto failed;}Yield(1);}
 if(p->config_key[0]){r=InstallSetConfig(p->config_key,p->config_value);if(r<0)goto failed;}join(entry,root,p->entry);if(p->shortcut[0]){r=shortcut(p->shortcut,entry,p->name);if(r<0)goto failed;}if(p->association[0]){join(path,BASE "/assoc",p->association);r=InstallWriteFile(path,entry,strlen(entry));if(r<0)goto failed;}
 memset(&old_record,0,sizeof(old_record));old_record.magic=APP_RECORD_MAGIC;copy(old_record.root,root);copy(old_record.source,source);memcpy(&old_record.manifest,p,sizeof(*p));old_record.manifest.components=components;r=InstallRegisterUninstall(&old_record);if(r<0)goto failed;join(path,BASE "/cache",p->id);copy(path+strlen(path),".sxp");r=InstallWriteFile(path,p,p->total_bytes);if(r<0)goto failed;r=InstallCommit();if(r<0){InstallLog("Commit/recovery required");return r;}return 0;
 failed:InstallLog("Install failed; restoring transaction");if(InstallRollback()<0)return S_BUSY;return r;}
int Uninstall(const char *id){if(!safe_id(id))return S_INVALID;char path[128];record_path(path,id);int n=Read(path,&old_record,sizeof(old_record));if(n!=(int)sizeof(old_record)||!record_valid(&old_record)||!streq(old_record.manifest.id,id))return S_INVALID;int r=InstallBegin();if(r<0)return r;for(u32 i=0;i<old_record.manifest.files;i++)if(old_record.manifest.file[i].component&old_record.manifest.components){join(path,old_record.root,old_record.manifest.file[i].path);r=remove_file(path);if(r<0)goto failed;}if(old_record.manifest.shortcut[0]){join(path,"/home/user/Desktop",old_record.manifest.shortcut);copy(path+strlen(path),".lnk");r=remove_file(path);if(r<0)goto failed;join(path,BASE "/menu",old_record.manifest.shortcut);copy(path+strlen(path),".lnk");r=remove_file(path);if(r<0)goto failed;}if(old_record.manifest.config_key[0]){join(path,BASE "/config",old_record.manifest.config_key);r=remove_file(path);if(r<0)goto failed;}if(old_record.manifest.association[0]){join(path,BASE "/assoc",old_record.manifest.association);r=remove_file(path);if(r<0)goto failed;}join(path,BASE "/cache",id);copy(path+strlen(path),".sxp");r=remove_file(path);if(r<0)goto failed;record_path(path,id);r=remove_file(path);if(r<0)goto failed;r=InstallCommit();/* Preserve installation directory and user-created files. */InstallLog("Uninstall complete; user files preserved");return r;
 failed:if(InstallRollback()<0)return S_BUSY;return r;}
